"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { isChunkLoadError, reloadForChunkErrorOnce } from "@/lib/chunk-error";

export function ErrorState({
  error,
  reset,
  context,
  home = "/",
  homeLabel = "Go home",
}: {
  error: Error & { digest?: string };
  reset: () => void;
  context: string;
  home?: string;
  homeLabel?: string;
}) {
  const [reloading, setReloading] = useState(false);

  useEffect(() => {
    // Best-effort report to the server error pipeline.
    try {
      fetch("/api/log", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          context,
          message: error?.message,
          digest: error?.digest,
          stack: error?.stack,
          path: typeof window !== "undefined" ? window.location.pathname : undefined,
        }),
        keepalive: true,
      }).catch(() => {});
    } catch {
      /* ignore */
    }
  }, [error, context]);

  useEffect(() => {
    if (!isChunkLoadError(error)) return;
    if (reloadForChunkErrorOnce()) setReloading(true);
  }, [error]);

  if (reloading) {
    return (
      <div className="grid min-h-[70vh] place-items-center px-4 py-16">
        <p className="text-sm text-slate-400">Updating…</p>
      </div>
    );
  }

  return (
    <div className="grid min-h-[70vh] place-items-center px-4 py-16">
      <div className="card max-w-md text-center">
        <div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-full bg-red-500/10 text-2xl">⚠️</div>
        <h1 className="mb-2 text-xl font-semibold">Something went wrong</h1>
        <p className="mb-1 text-sm text-slate-400">
          We hit an unexpected error and our team has been notified. You can retry, or head back.
        </p>
        {error?.digest && (
          <p className="mb-5 font-mono text-xs text-slate-600">ref: {error.digest}</p>
        )}
        <div className="flex items-center justify-center gap-3">
          <button onClick={() => reset()} className="btn-primary">
            Try again
          </button>
          <Link href={home} className="btn-secondary">
            {homeLabel}
          </Link>
        </div>
      </div>
    </div>
  );
}
