"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { retryProvision } from "@/lib/actions-server-lifecycle";

/**
 * Shown on the server detail page when a server is stranded in ERROR because its
 * PROVISION failed. Before this, an ERROR server rendered a bare red status dot
 * with no message, no way to retry, and the normal start/stop controls that
 * couldn't help. Mirrors the "Setup failed + retry" affordance the hosting,
 * email and sites products already give (HostingClient, EmailHosting,
 * SitesManager): a clear red banner, a Retry action, and a support link.
 */
export function ProvisionErrorBanner({
  serverId,
  reason,
}: {
  serverId: string;
  reason?: string | null;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);

  return (
    <div className="card mb-6 border-red-500/30 bg-red-500/[0.06]">
      <h2 className="font-semibold text-red-300">Provisioning failed</h2>
      <p className="mt-1 text-sm text-red-300/90">
        We couldn&apos;t finish setting up this server{reason ? <>: <span className="font-medium">{reason}</span></> : "."}{" "}
        Our team has been notified. You can retry the setup, or contact support if it keeps failing.
      </p>
      <div className="mt-4 flex flex-wrap items-center gap-2">
        <button
          className="btn-primary"
          disabled={pending}
          onClick={() =>
            start(async () => {
              setError(null);
              const res = await retryProvision(serverId);
              if (res?.error) setError(res.error);
            })
          }
        >
          {pending ? "Retrying…" : "Retry provision"}
        </button>
        <Link href="/dashboard/support" className="btn-secondary">
          Contact support
        </Link>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}
