"use client";

import { useState } from "react";

/** Snapshot thresholds — instantaneous values already computed on the page, not a
 * "sustained N minutes" tracker. Simple on purpose (see ProvisionErrorBanner /
 * BackupTierUpsell for the same "small presentational banner" convention). */
const RAM_THRESHOLD_PCT = 90;
const DISK_THRESHOLD_PCT = 90;
const CPU_THRESHOLD_PCT = 90;

/**
 * "You're running low on X — consider upgrading" banner. Pure presentational:
 * renders nothing if every metric is below its threshold, and nothing if a
 * metric wasn't supplied (undefined/null — e.g. VPS overview has no per-page
 * disk sample, so `diskPct` is simply omitted there rather than faked).
 *
 * Dismissible for the current page view only (local state, no persistence) —
 * this is a nudge, not a notification center entry.
 */
export function ResourceLimitAlert({
  cpuPct,
  memPct,
  diskPct,
  upgradeHref,
}: {
  cpuPct?: number | null;
  memPct?: number | null;
  diskPct?: number | null;
  /** Where "Upgrade" should take the customer — the resize/storage section. */
  upgradeHref: string;
}) {
  const [dismissed, setDismissed] = useState(false);

  const hot: string[] = [];
  if (typeof cpuPct === "number" && cpuPct >= CPU_THRESHOLD_PCT) hot.push("CPU");
  if (typeof memPct === "number" && memPct >= RAM_THRESHOLD_PCT) hot.push("RAM");
  if (typeof diskPct === "number" && diskPct >= DISK_THRESHOLD_PCT) hot.push("disk");

  if (dismissed || hot.length === 0) return null;

